function drawMatrix(el,R,r){const pts=R.rows.filter(x=>(R.popShare?x.peopleNeed:x.ctx)!=null),acc=new Set(R.accelerate.map(x=>x.key)),exp=new Set(R.expand.map(x=>x.key));
