    t = text.lower()
    found: list[str] = []
    for pat, code in REGION_ALIASES:
        if re.search(pat, t) and code not in found:
            found.append(code)
    taken = t
    for pat, code in _country_patterns():
        if pat.search(taken) and code not in found:
            found.append(code)
            taken = pat.sub(" ", taken)
