    if re.search(r"\bifc\b", t):
        out["org"] = "IFC"
    elif re.search(r"\bmiga\b", t):
        out["org"] = "MIGA"
    elif re.search(r"\bworld bank\b(?! group)|\bibrd\b|\bida\b", t):
        out["org"] = "WB"
