class OverviewArgs(BaseModel):
    outcome_id: int | None = None
    area: str = "ACW"
    _v_area = field_validator("area")(lambda cls, v: _area(v))


class SearchArgs(BaseModel):
    query: str = Field(min_length=2, max_length=80)


class DefArgs(BaseModel):
    ind_code: str
